MonitorDialog::~MonitorDialog(){displayTimer.stop();poll.stop();nvidiaTimeout.stop();sensorsTimeout.stop();disconnect(&nvidia,nullptr,this,nullptr);disconnect(&sensors,nullptr,this,nullptr);nvidia.killTree();sensors.killTree();nvidia.waitForFinished(1000);sensors.waitForFinished(1000);}
void MonitorDialog::updateSummary(){
    const auto s=performance?performance->snapshot():ModelPerformanceSnapshot{};auto seconds=qMax<qint64>(0,s.uptimeMs/1000);const auto elapsed=QString("%1:%2:%3").arg(seconds/3600,2,10,QChar('0')).arg(seconds/60%60,2,10,QChar('0')).arg(seconds%60,2,10,QChar('0'));
    modelName->setText(s.model.isEmpty()?"Модель не запущена":s.model);modelName->setToolTip(s.model);modelState->setText((s.running?QString("Сервер работает · "):QString("Остановлен · "))+elapsed);prefillSpeed->setText(s.promptSpeed<0?QString("— ток/с"):shown(s.promptSpeed," ток/с",1));generationSpeed->setText(s.generationSpeed<0?QString("— ток/с"):shown(s.generationSpeed," ток/с",1));prefillSpeed->setToolTip(s.promptLive?"Промежуточная скорость префилла из журнала":"Префилл из итогового отчёта журнала, токенов в секунду");generationSpeed->setToolTip(s.generationLive?"Генерация за окно около 3 секунд из журнала":"Генерация из итогового отчёта журнала, токенов в секунду");
    if(s.task.isEmpty())modelDetails->setText("Журнал сервера · ожидается отчёт о скорости");else modelDetails->setText(s.task+"\n"+(s.promptLive||s.generationLive?QString("Промежуточный отчёт"):QString("Итоговый отчёт"))+" · "+QString::number(qMax<qint64>(0,s.reportAgeMs/1000))+" с назад"+(s.requestMs>=0?"\nЗапрос: "+shown(s.requestMs/1000.0," с",2):QString()));
    QStringList cards,tooltips;for(int row=0;row<gpus->rowCount();++row){if(!gpus->item(row,6))continue;auto name=gpus->item(row,0)->text();cards<<name.section('\n',0,0)+"\nGPU "+gpus->item(row,2)->text()+" · "+gpus->item(row,1)->text()+"\nVRAM "+gpus->item(row,3)->text();tooltips<<name+"\nМощность: "+gpus->item(row,4)->text()+" · вентилятор: "+gpus->item(row,5)->text()+"\nОбновлено: "+gpus->item(row,6)->text();}gpuSummary->setText(cards.isEmpty()?QString("GPU · данные недоступны"):cards.join("\n\n"));gpuSummary->setToolTip(tooltips.isEmpty()?gpuStatus->text():tooltips.join("\n\n"));
    double cpuMaximum=-1;for(int row=0;row<sensorTable->rowCount();++row){if(!sensorTable->item(row,4))continue;if(sensorTable->item(row,0)->text().contains("cpu",Qt::CaseInsensitive)&&sensorTable->item(row,2)->text()==QString::fromUtf8("Температура")){bool ok=false;auto value=sensorTable->item(row,3)->text().section(' ',0,0).toDouble(&ok);if(ok)cpuMaximum=qMax(cpuMaximum,value);}}temperatureSummary->setText(cpuMaximum<0?QString("CPU t° · н/д (LHM)"):"CPU t° max · "+shown(cpuMaximum," °C",1));
}
void MonitorDialog::sample(){
    const auto r=sampler.sample();cpu->setEnabled(r.cpuPercent>=0);cpu->setValue(r.cpuPercent<0?0:qRound(r.cpuPercent));cpuText->setText("CPU · "+shown(r.cpuPercent," %",1));double memory=-1;if(r.memoryTotal){memory=100.0*r.memoryUsed/r.memoryTotal;ram->setEnabled(true);ram->setValue(qRound(memory));ramText->setText(QString("RAM · %1 / %2 ГиБ · %3 %").arg(r.memoryUsed/1073741824.0,0,'f',2).arg(r.memoryTotal/1073741824.0,0,'f',2).arg(memory,0,'f',1));}else{ram->setEnabled(false);ramText->setText("Недоступно на этой платформе");}history->add(r.cpuPercent,memory);
    if(smi.isEmpty())gpuStatus->setText("nvidia-smi не найден. Установите драйвер NVIDIA; для других GPU используйте вкладку дополнительных датчиков.");else if(nvidia.state()==QProcess::NotRunning){nvidia.start(smi,{"--query-gpu=uuid,name,temperature.gpu,utilization.gpu,memory.used,memory.total,power.draw,fan.speed","--format=csv,noheader,nounits"});nvidiaTimeout.start(4500);}
    if(sensorTick++%3==0)sampleSensors();
}
void MonitorDialog::sampleSensors(){
    if(!hardwareSensors->isChecked()||sensors.state()!=QProcess::NotRunning)return;if(!QFileInfo::exists(powershell)){sensorStatus->setText("Опрос WMI доступен в Windows через штатный Windows PowerShell.");return;}
    // Use the OS-supplied Windows PowerShell, not optional pwsh.exe. No shell interpolation or profile scripts.
    const QString script="[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false); $ErrorActionPreference='Stop'; try { $s=@(Get-CimInstance -Namespace root/LibreHardwareMonitor -ClassName Sensor -OperationTimeoutSec 3 | Where-Object { $_.SensorType -in @('Temperature','Load','Fan','Power','Clock') } | Select-Object Parent,Name,SensorType,Value); ConvertTo-Json -InputObject $s -Compress } catch { exit 2 }";
    sensors.start(powershell,{"-NoLogo","-NoProfile","-NonInteractive","-Command",script});sensorsTimeout.start(5500);
}
